INSERT INTO `page` (`id`, `alias`, `seolink`, `name`, `title`, `main`, `promo`, `content`, `status`, `meta_title`, `meta_description`, `meta_keywords`, `date`, `update_at`) VALUES (1,'main','','Main','Страница 1',1,'<div class=\"top-descrr\">Скидки от 40%</div>\r\n<div class=\"top-descrr\">Оплата после примерки</div>\r\n<div class=\"top-descrr\">Возврат/обмен 14 дней</div>\r\n<div class=\"top-descrr\">Доставка от 0 руб</div>','Демонстрационная страница. Текст в архив не входит.',1,'Купить угги в интернет-магазине | @name@','Купить австралийские угги по демократичной цене. Доставка с примеркой по России. Оплата после примерки.','ugg australia интернет магазин, австралийские угги, обувь ugg australia','2018-09-07 15:23:52','2021-04-17 20:27:35');
INSERT INTO `page` (`id`, `alias`, `seolink`, `name`, `title`, `main`, `promo`, `content`, `status`, `meta_title`, `meta_description`, `meta_keywords`, `date`, `update_at`) VALUES (2,'contacts','contacts','contacts','Страница 2',0,'','Демонстрационная страница. Текст в архив не входит.',1,'Интернет-магазин @shop_name@ - Контакты','Интернет-магазин @shop_name@, тел.: @shop_tel@, email: @shop_email@, адрес: @shop_adress@','контакты','2018-09-07 15:23:52','2021-01-24 15:53:40');
